<details><summary>Edit weekly routine</summary><p>The example is a starting point. Set your actual habits and times before applying. Activities ending before their start continue into the next morning.</p><form method="post" data-routine-form><?=csrf_field()?><input type="hidden" name="action" value="routine_save"><input type="hidden" name="version" value="<?=(int)($routine['version']??0)?>"><label>Routine timezone<select name="timezone"><?php foreach(DateTimeZone::listIdentifiers()as$tz):?><option <?=$tz===$routinePreview['timezone']?'selected':''?>><?=e($tz)?></option><?php endforeach;?></select></label><div data-routine-rows><?php foreach($routinePreview['rows']as$i=>$rr)$routineEditorRow($rr,(string)$i);?></div><button class="wbtn" type="button" data-routine-add>Add activity</button><input type="hidden" name="routine_complete" value="1"><button class="wbtn primary">Save routine template</button></form><template id="routine-row-template"><?php $routineEditorRow(['title'=>'','start'=>'09:00','end'=>'09:30','days'=>[1,2,3,4,5],'kind'=>'personal'],'ROW_INDEX');?></template><p role="status" data-routine-status></p></details><script src="<?=asset('js/weekly-routine.js')?>" defer></script>
